-- slc.semantic.nyc_trips (governed profile). Generated by build_metric_views.py.
CREATE OR REPLACE VIEW slc.semantic.nyc_trips
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: NYC Yellow Taxi trips (B-N1 to B-N5, N-S1, N-S2, N-M1, N-M2, N-C1, N-C2). Pickup and dropoff zones and dates are
  role-played.
source: slc.nyctaxi.fact_trip
joins:
- name: pickup_cal
  source: slc.nyctaxi.dim_date
  'on': source.pickup_date = pickup_cal.date_key
  rely:
    at_most_one_match: true
- name: pu
  source: slc.nyctaxi.dim_zone
  'on': source.pu_location_id = pu.location_id
  rely:
    at_most_one_match: true
- name: dz
  source: slc.nyctaxi.dim_zone
  'on': source.do_location_id = dz.location_id
  rely:
    at_most_one_match: true
- name: pay
  source: slc.nyctaxi.dim_payment_type
  'on': source.payment_type = pay.payment_type
  rely:
    at_most_one_match: true
fields:
- name: pickup_date
  expr: source.pickup_date
  comment: Date the trip started; the anchor for year-to-date and pace metrics.
  display_name: Pickup Date
  synonyms:
  - trip date
  - pickup day
  - date
- name: pickup_year
  expr: CAST(DATE_TRUNC('YEAR', pickup_date) AS DATE)
  comment: First day of the pickup calendar year; YTD windows reset here.
  display_name: Pickup Year
- name: pickup_quarter
  expr: CAST(DATE_TRUNC('QUARTER', pickup_date) AS DATE)
  comment: First day of the pickup calendar quarter.
  display_name: Pickup Quarter
- name: pickup_month
  expr: CAST(DATE_TRUNC('MONTH', pickup_date) AS DATE)
  comment: First day of the pickup calendar month; MTD windows reset here.
  display_name: Pickup Month
- name: pickup_day_of_week
  expr: pickup_cal.day_of_week
  comment: ISO day of week of the pickup date, Monday = 1.
  display_name: Pickup Day Of Week
- name: pickup_day_name
  expr: pickup_cal.day_name
  display_name: Pickup Day Name
- name: pickup_hour
  expr: source.pickup_hour
  comment: Hour of day the trip started, 0-23.
  display_name: Pickup Hour
  synonyms:
  - hour
  - time of day
  - hour of day
- name: dropoff_date
  expr: source.dropoff_date
  comment: Date the trip ended (role of the Date dimension); differs from pickup date for trips crossing midnight.
  display_name: Dropoff Date
  synonyms:
  - dropoff day
  - trip end date
  - arrival date
- name: dropoff_year
  expr: YEAR(dropoff_date)
  comment: Calendar year of the dropoff date.
  display_name: Dropoff Year
- name: dropoff_month
  expr: CAST(DATE_TRUNC('MONTH', dropoff_date) AS DATE)
  comment: First day of the dropoff calendar month.
  display_name: Dropoff Month
- name: pickup_zone_id
  expr: source.pu_location_id
  comment: TLC location id of the pickup zone.
  display_name: Pickup Zone ID
- name: pickup_zone
  expr: pu.zone
  comment: TLC taxi zone where the trip started (role of the Zone dimension).
  display_name: Pickup Zone
  synonyms:
  - origin
  - pickup location
  - from
- name: pickup_borough
  expr: pu.borough
  comment: Borough of the pickup zone.
  display_name: Pickup Borough
- name: pickup_service_zone
  expr: pu.service_zone
  comment: TLC service zone of the pickup zone (Yellow Zone, Boro Zone, Airports, EWR).
  display_name: Pickup Service Zone
- name: dropoff_zone_id
  expr: source.do_location_id
  comment: TLC location id of the dropoff zone.
  display_name: Dropoff Zone ID
- name: dropoff_zone
  expr: dz.zone
  comment: TLC taxi zone where the trip ended (role of the Zone dimension).
  display_name: Dropoff Zone
  synonyms:
  - destination
  - dropoff location
  - to
- name: dropoff_borough
  expr: dz.borough
  comment: Borough of the dropoff zone.
  display_name: Dropoff Borough
- name: dropoff_service_zone
  expr: dz.service_zone
  display_name: Dropoff Service Zone
- name: payment_type
  expr: source.payment_type
  comment: TLC payment type code.
  display_name: Payment Type Code
- name: payment_type_name
  expr: pay.payment_type_name
  comment: TLC payment type code and label (0 Flex Fare trip, 1 Credit card, 2 Cash, 3 No charge, 4 Dispute, 5 Unknown, 6
    Voided trip).
  display_name: Payment Type
  synonyms:
  - payment method
  - paid by
  - tender
- name: vendor_id
  expr: source.vendor_id
  comment: TLC technology provider id that recorded the trip.
  display_name: Vendor
  synonyms:
  - vendor id
  - provider
  - TPEP provider
measures:
- name: trip_count
  expr: COUNT(1)
  comment: Count of valid Yellow Taxi trips (fact_trip rows).
  display_name: Trip Count
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - trips
  - number of trips
  - rides
  - ride count
- name: total_trip_distance
  expr: SUM(trip_distance)
  comment: Sum of trip distance in miles (fact_trip.trip_distance).
  display_name: Total Trip Distance
  format:
    type: number
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - miles
  - distance
  - total miles
  - trip miles
- name: fare_amount
  expr: SUM(source.fare_amount)
  comment: Sum of metered fares (fact_trip.fare_amount), excluding tips, tolls and surcharges.
  display_name: Fare Amount
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - fares
  - metered fare
  - fare revenue
- name: tip_amount
  expr: SUM(source.tip_amount)
  comment: Sum of recorded tips across all payment types (fact_trip.tip_amount). TLC records tips only for card payments.
  display_name: Tip Amount (All Payment Types)
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - tips
  - all tips
  - gratuity
- name: tolls_amount
  expr: SUM(source.tolls_amount)
  comment: Sum of tolls (fact_trip.tolls_amount).
  display_name: Tolls Amount
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - tolls
  - toll charges
  - bridge and tunnel tolls
- name: gross_trip_revenue
  expr: SUM(total_amount)
  comment: Sum of total amount charged (fact_trip.total_amount).
  display_name: Gross Trip Revenue
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - revenue
  - trip revenue
  - total amount
  - gross revenue
  - takings
- name: card_tips
  expr: SUM(source.tip_amount) FILTER (WHERE source.payment_type = 1)
  comment: Sum of tips on credit card trips (payment type 1); blank for other payment types.
  display_name: Card Tips
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - credit card tips
  - card gratuity
  - tips on card
- name: distinct_od_pairs
  expr: COUNT(DISTINCT od_pair_id)
  comment: Exact count of distinct pickup zone to dropoff zone pairs. Additive across zone and borough of either role; not
    additive across time, payment type, vendor or hour.
  display_name: Distinct OD Pairs
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - origin destination pairs
  - OD pairs
  - unique routes
  - distinct routes
- name: fare_per_mile
  expr: CAST(MEASURE(fare_amount) AS DOUBLE) / NULLIF(CAST(MEASURE(total_trip_distance) AS DOUBLE), 0)
  comment: Fare Amount divided by Total Trip Distance, computed from the aggregated sums at every grain.
  display_name: Fare per Mile
  format:
    type: number
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - fare per mile
  - price per mile
  - rate per mile
- name: revenue_ytd
  expr: SUM(total_amount)
  comment: Gross Trip Revenue from 1 January of the pickup year to the last pickup date in context.
  display_name: Revenue YTD
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - year to date revenue
  - YTD revenue
  window:
  - order: pickup_date
    range: cumulative
  - order: pickup_year
    range: current
- name: revenue_stly_ytd
  expr: SUM(total_amount)
  comment: Revenue YTD shifted back one year along the pickup date (29 February maps to 28 February).
  display_name: Revenue YTD Same Time Last Year
  format:
    type: currency
    currency_code: USD
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - STLY revenue
  - last year YTD
  - prior year to date revenue
  - same time last year
  window:
  - order: pickup_date
    range: cumulative
    offset: -1 year
  - order: pickup_year
    range: current
    offset: -1 year
- name: revenue_yoy_pct
  expr: (CAST(MEASURE(revenue_ytd) AS DOUBLE) - CAST(MEASURE(revenue_stly_ytd) AS DOUBLE)) / NULLIF(CAST(MEASURE(revenue_stly_ytd)
    AS DOUBLE), 0)
  comment: Year-over-year change of Revenue YTD against the same period last year.
  display_name: Revenue YoY % vs STLY
  format:
    type: percentage
    decimal_places:
      type: exact
      places: 2
  synonyms:
  - YoY growth
  - year over year
  - growth vs last year
- name: trips_mtd
  expr: COUNT(1)
  comment: Trips from the first day of the pickup month to the last pickup date in context.
  display_name: Trips MTD
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - month to date trips
  window:
  - order: pickup_date
    range: cumulative
  - order: pickup_month
    range: current
- name: trips_ytd
  expr: COUNT(1)
  comment: Trips from 1 January of the pickup year to the last pickup date in context.
  display_name: Trips YTD
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  synonyms:
  - year to date trips
  window:
  - order: pickup_date
    range: cumulative
  - order: pickup_year
    range: current
- name: days_elapsed_in_month
  expr: MAX(DAYOFMONTH(pickup_date))
  comment: Day of month of the last pickup date in context (calendar days elapsed).
  display_name: Days Elapsed in Month
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  window:
  - order: pickup_date
    range: current
    semiadditive: last
- name: days_elapsed_in_year
  expr: MAX(DAYOFYEAR(pickup_date))
  comment: Day of year of the last pickup date in context (calendar days elapsed).
  display_name: Days Elapsed in Year
  format:
    type: number
    decimal_places:
      type: exact
      places: 0
  window:
  - order: pickup_date
    range: current
    semiadditive: last
- name: pace_index
  expr: (CAST(MEASURE(trips_mtd) AS DOUBLE) / MEASURE(days_elapsed_in_month)) / NULLIF(CAST(MEASURE(trips_ytd) AS DOUBLE)
    / MEASURE(days_elapsed_in_year), 0)
  comment: Average daily trips month-to-date divided by average daily trips year-to-date, using calendar days elapsed. Above
    1 means the month is running ahead of the year's pace.
  display_name: MTD-to-YTD Daily Pace Index
  format:
    type: number
    decimal_places:
      type: exact
      places: 3
  synonyms:
  - pace index
  - run rate index
  - month pace
  - daily pace
$$;
